// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }

    function testFuzz_property(uint256 seed, address actor) public {
        // The contract is freshly deployed in setUp(): no initializer has run,
        // so the PausableUpgradeable _paused flag is false and the manager is
        // unpaused. `paused()` is a pure view of that flag; no fuzzed input can
        // change the fact that a just-deployed C is unpaused.
        // (seed/actor are admissible but irrelevant — the property is universal.)
        vm.assume(actor != address(0));
        seed;
        actor;

        bool ok;
        bool reported;
        try c.paused() returns (bool p) {
            ok = true;
            reported = p;
        } catch {
            ok = false;
        }

        // General rule: for every admissible input, the view call `paused()`
        // on a freshly deployed (never paused) C completes and reports false.
        // The mutant's paused() always returns true, breaking the rule.
        assertTrue(ok && !reported);
    }
}
